function predict_sr(pc: uint64) -> int32:
    sR = 0
    for bank_idx in 0..7:
        // 1. Evaluate usefulness for all registers assigned to this bank
        // Bank 0 tracks 9 registers (R0, R8, ..., R64); Banks 1-7 track 8 registers each (stride-8 interleaving)
        bank_regs = [reg for reg in 0..64 if reg % 8 == bank_idx]
        ut0_idx = hash_ut0(pc)
        ut1_idx = hash_ut1(pc)
        ut2_idx = hash_ut2(pc)

        best_reg = null
        max_useful = -INFINITY

        for reg in bank_regs:
            if register_tracking_table[reg].valid == 1 and register_tracking_table[reg].decay_ctr > 0:
                useful_weight = ut_tables[bank_idx].UT0[ut0_idx][reg] +
                                ut_tables[bank_idx].UT1[ut1_idx][reg] +
                                ut_tables[bank_idx].UT2[ut2_idx][reg]
                if useful_weight > max_useful:
                    max_useful = useful_weight
                    best_reg = reg

        // 2. Query prediction weight tables if an available register exists
        if best_reg != null:
            digest = register_tracking_table[best_reg].payload[11:0]
            h0 = hash_wt0(pc, digest) // 9 index bits for 512 entries
            h1 = hash_wt1(pc, digest) // 8 index bits for 256 entries
            h2 = hash_wt2(pc, digest) // 7 index bits for 128 entries

            wt_sum = wt_tables[bank_idx].WT0[h0] +
                     wt_tables[bank_idx].WT1[h1] +
                     wt_tables[bank_idx].WT2[h2]

            // Scale bank contribution: x2.5 if useful (when max_useful > 0), else x0
            if max_useful > 0:
                bank_contrib = int(wt_sum * 2.5) // fixed-point implementation: (wt_sum * 5) >> 1
            else:
                bank_contrib = 0
            sR += bank_contrib
        else:
            sR += 0

    return sR
